style.css:
/* Black Cathedral — Pinterest */
:root {
  /* Swap these colours if you want a different gothic palette */
  --my-bg: #100d12;
  --my-panel: #1b151e;
  --my-red: #6f1828;
  --my-silver: #a99eae;
  --my-text: #d5c9d9;
  --my-border: #483344;
}

/* Gothic typography */
body,
button,
input,
textarea,
[role="button"] {
  font-family: "Blackletter (Steffmann)", "UnifrakturCook",
    "Old English Text MT", serif !important;
  color: var(--my-text) !important;
}

/* Dark cathedral atmosphere */
html,
body {
  background-color: var(--my-bg) !important;
  background-image:
    radial-gradient(ellipse at top, #352130 0%, transparent 55%),
    linear-gradient(180deg, #100d12, #09070b) !important;
}

/* Dark panels and surfaces */
header,
nav,
[role="navigation"],
[role="dialog"] {
  background-color: var(--my-panel) !important;
  border-color: var(--my-border) !important;
}

/* Gothic borders and muted silver text */
a {
  color: var(--my-silver) !important;
}

button {
  border-color: var(--my-border) !important;
}

/* Search bar — dark velvet and silver edge */
input[type="text"],
input[type="search"],
input:not([type]) {
  background-color: #211722 !important;
  color: var(--my-text) !important;
  border: 1px solid var(--my-border) !important;
  border-radius: 18px !important;
}

/* Pinterest cards */
[data-test-id="pin"],
article {
  border-radius: 10px !important;
}

/* Gothic hover glow */
a:hover,
button:hover {
  color: #e2b6c4 !important;
  text-shadow: 0 0 8px #7e263d !important;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 8px !important;
}

::-webkit-scrollbar-track {
  background: #100d12 !important;
}

::-webkit-scrollbar-thumb {
  background: #492b3d !important;
  border-radius: 8px !important;
}
